<?php require 'config.php';require_admin();verify_csrf();$a=read_json('maintenance.json',[]);if($_SERVER['REQUEST_METHOD']==='POST'){foreach($a as &$x)if($x['id']===$_POST['id'])$x['status']=$_POST['status'];write_json('maintenance.json',$a);redirect('maintenance.php');}$title='طلبات الصيانة';require 'header.php';?><h1>🔧 طلبات الصيانة</h1><table class="table"><tr><th>العميل</th><th>الجهاز</th><th>المشكلة</th><th>الحالة</th></tr><?php foreach($a as $x):?><tr><td><?=e($x['name'].' / '.$x['phone'])?></td><td><?=e($x['device'].' '.$x['model'])?></td><td><?=e($x['problem'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=e($x['id'])?>"><select name="status"><option value="new">جديد</option><option value="working">قيد العمل</option><option value="done">تم</option><option value="cancelled">ملغي</option></select><button class="btn">حفظ</button></form></td></tr><?php endforeach;?></table><?php require 'footer.php';?>